import type { LiveHistoryTurn } from "./speech";

/**
 * Build the conversation seed for a live voice session.
 *
 * A voice session opens a separate model connection, so without a seed the
 * model has no idea what was just discussed in text and reintroduces itself
 * mid-lesson. Only plain user/assistant text is replayed: tool traffic and
 * generative-UI payloads mean nothing to a speech model and would waste the
 * audio context window, which is far smaller than the text one.
 */
export const DEFAULT_LIVE_HISTORY_TURNS = 12;
export const DEFAULT_LIVE_HISTORY_CHARS = 6000;

function turnText(message: unknown): string {
	const content = (message as { content?: unknown }).content;
	if (typeof content === "string") return content.trim();
	if (Array.isArray(content)) {
		return content
			.filter((part) => part?.type === "text" && typeof part.text === "string")
			.map((part) => (part.text as string).trim())
			.filter(Boolean)
			.join(" ")
			.trim();
	}
	return "";
}

function turnRole(message: unknown): LiveHistoryTurn["role"] | null {
	const role = (message as { role?: unknown }).role;
	if (role === "assistant") return "assistant";
	// "user-with-attachments" carries the same learner intent as a plain turn;
	// the attachments themselves are dropped along with the other non-text parts.
	if (role === "user" || role === "user-with-attachments") return "user";
	return null;
}

export function buildLiveHistory(
	messages: readonly unknown[],
	options: { maxTurns?: number; maxChars?: number } = {},
): LiveHistoryTurn[] {
	const maxTurns = Math.max(0, options.maxTurns ?? DEFAULT_LIVE_HISTORY_TURNS);
	const maxChars = Math.max(0, options.maxChars ?? DEFAULT_LIVE_HISTORY_CHARS);
	if (maxTurns === 0 || maxChars === 0) return [];

	const turns: LiveHistoryTurn[] = [];
	// Walk backwards so that when the budget runs out it is the oldest turns
	// that are dropped, not the ones the learner just spoke about.
	for (let i = messages.length - 1; i >= 0 && turns.length < maxTurns; i -= 1) {
		const role = turnRole(messages[i]);
		if (!role) continue;
		const text = turnText(messages[i]);
		if (!text) continue;
		turns.push({ role, text });
	}
	turns.reverse();

	let total = 0;
	const budgeted: LiveHistoryTurn[] = [];
	for (let i = turns.length - 1; i >= 0; i -= 1) {
		total += turns[i].text.length;
		if (total > maxChars) break;
		budgeted.push(turns[i]);
	}
	return budgeted.reverse();
}

/**
 * Provider-agnostic frame capture for live sessions.
 *
 * Both realtime providers Keating targets consume sampled JPEG frames rather
 * than a continuous video track — Gemini Live has a dedicated video lane capped
 * at 1 fps, and GPT Realtime accepts still images as conversation items. So
 * there is one capture pipeline here and the providers supply their own sink.
 *
 * Nothing in this module may import provider types.
 */

/** Both providers cap video at one frame per second. */
export const MIN_FRAME_INTERVAL_MS = 1000;
export const DEFAULT_MAX_EDGE = 768;
export const DEFAULT_JPEG_QUALITY = 0.6;
/**
 * Histogram distance below which a frame is considered a repeat of the previous
 * one and skipped. Tuned to drop a static desk/screen while still catching a
 * page scroll or a hand entering frame.
 */
export const DEFAULT_SIMILARITY_THRESHOLD = 0.02;

const HISTOGRAM_BINS = 32;

export type VideoSource = "camera" | "screen";

export interface VideoCaptureOptions {
	source?: VideoSource;
	/** Milliseconds between sampled frames. Floored to MIN_FRAME_INTERVAL_MS. */
	intervalMs?: number;
	/** Longest edge of the encoded frame, in pixels. */
	maxEdge?: number;
	jpegQuality?: number;
	/** Set to 0 to emit every frame regardless of similarity. */
	similarityThreshold?: number;
}

export interface NormalizedCaptureOptions {
	source: VideoSource;
	intervalMs: number;
	maxEdge: number;
	jpegQuality: number;
	similarityThreshold: number;
}

export interface CapturedFrame {
	/** Base64 JPEG payload, no data-URL prefix. */
	data: string;
	/** Full data URL, which is what the OpenAI image content part wants. */
	dataUrl: string;
	mimeType: "image/jpeg";
	width: number;
	height: number;
	capturedAt: number;
}

export type FrameListener = (frame: CapturedFrame) => void;

export interface VideoCaptureHandle {
	/** Live stream, for rendering a local preview. */
	readonly stream: MediaStream;
	readonly source: VideoSource;
	/** Frames emitted so far, including on-demand captures. */
	readonly frameCount: number;
	/** Subscribe to the sampled frame feed. Returns an unsubscribe function. */
	onFrame(listener: FrameListener): () => void;
	/** Grab a frame immediately, bypassing the interval and similarity skip. */
	captureFrameNow(): Promise<CapturedFrame | null>;
	stop(): void;
}

export function normalizeCaptureOptions(options: VideoCaptureOptions = {}): NormalizedCaptureOptions {
	return {
		source: options.source === "screen" ? "screen" : "camera",
		intervalMs: Math.max(MIN_FRAME_INTERVAL_MS, Math.floor(options.intervalMs ?? MIN_FRAME_INTERVAL_MS)),
		maxEdge: Math.max(64, Math.floor(options.maxEdge ?? DEFAULT_MAX_EDGE)),
		jpegQuality: Math.min(1, Math.max(0.1, options.jpegQuality ?? DEFAULT_JPEG_QUALITY)),
		similarityThreshold: Math.max(0, options.similarityThreshold ?? DEFAULT_SIMILARITY_THRESHOLD),
	};
}

/**
 * Scale a frame so its longest edge is at most maxEdge, preserving aspect
 * ratio. Frames already within budget are left alone — upscaling would only
 * cost tokens without adding detail.
 */
export function computeCaptureSize(
	width: number,
	height: number,
	maxEdge: number,
): { width: number; height: number } {
	if (width <= 0 || height <= 0) return { width: 0, height: 0 };
	const longest = Math.max(width, height);
	if (longest <= maxEdge) return { width: Math.round(width), height: Math.round(height) };
	const scale = maxEdge / longest;
	return {
		width: Math.max(1, Math.round(width * scale)),
		height: Math.max(1, Math.round(height * scale)),
	};
}

/**
 * Normalized luma histogram over RGBA pixel data. Cheap enough to run on every
 * candidate frame and stable against sensor noise, which a per-pixel diff is
 * not.
 */
export function lumaHistogram(pixels: ArrayLike<number>, bins = HISTOGRAM_BINS): Float64Array {
	const histogram = new Float64Array(bins);
	const pixelCount = Math.floor(pixels.length / 4);
	if (pixelCount === 0) return histogram;
	for (let i = 0; i < pixelCount; i += 1) {
		const offset = i * 4;
		// Rec. 601 luma; the exact weights matter less than being consistent.
		const luma = 0.299 * pixels[offset] + 0.587 * pixels[offset + 1] + 0.114 * pixels[offset + 2];
		const bin = Math.min(bins - 1, Math.floor((luma / 256) * bins));
		histogram[bin] += 1;
	}
	for (let i = 0; i < bins; i += 1) histogram[i] /= pixelCount;
	return histogram;
}

/** Total variation distance between two normalized histograms, in [0, 1]. */
export function histogramDistance(a: ArrayLike<number>, b: ArrayLike<number>): number {
	if (a.length !== b.length) return 1;
	let sum = 0;
	for (let i = 0; i < a.length; i += 1) sum += Math.abs(a[i] - b[i]);
	return sum / 2;
}

export function framesAreSimilar(
	previous: ArrayLike<number> | null,
	next: ArrayLike<number>,
	threshold: number,
): boolean {
	if (previous === null || threshold <= 0) return false;
	return histogramDistance(previous, next) < threshold;
}

/**
 * True when a frame should not be sent: the document is hidden, or the frame is
 * indistinguishable from the last one we sent. Extracted so the policy is
 * testable without a camera.
 */
export function shouldSkipFrame(input: {
	documentHidden: boolean;
	previousHistogram: ArrayLike<number> | null;
	nextHistogram: ArrayLike<number>;
	similarityThreshold: number;
}): boolean {
	if (input.documentHidden) return true;
	return framesAreSimilar(input.previousHistogram, input.nextHistogram, input.similarityThreshold);
}

async function requestStream(source: VideoSource): Promise<MediaStream> {
	if (typeof navigator === "undefined" || !navigator.mediaDevices) {
		throw new Error("Video capture is unavailable in this environment.");
	}
	if (source === "screen") {
		if (!navigator.mediaDevices.getDisplayMedia) {
			throw new Error("Screen sharing is not supported by this browser.");
		}
		return await navigator.mediaDevices.getDisplayMedia({ video: true, audio: false });
	}
	if (!navigator.mediaDevices.getUserMedia) {
		throw new Error("Camera capture is not supported by this browser.");
	}
	return await navigator.mediaDevices.getUserMedia({
		video: { width: { ideal: 1280 }, height: { ideal: 720 } },
		audio: false,
	});
}

/**
 * Begin sampling frames from the camera or screen. The returned handle is inert
 * until something subscribes via onFrame; the timer runs regardless so that
 * captureFrameNow always has a warm video element.
 */
export async function startVideoCapture(options: VideoCaptureOptions = {}): Promise<VideoCaptureHandle> {
	const config = normalizeCaptureOptions(options);
	const stream = await requestStream(config.source);

	const video = document.createElement("video");
	video.autoplay = true;
	video.muted = true;
	video.playsInline = true;
	video.srcObject = stream;

	const canvas = document.createElement("canvas");
	const context = canvas.getContext("2d", { willReadFrequently: true });

	const listeners = new Set<FrameListener>();
	let previousHistogram: Float64Array | null = null;
	let frameCount = 0;
	let stopped = false;
	let timer: ReturnType<typeof setInterval> | null = null;

	await video.play().catch(() => {
		// Autoplay of a muted local stream is permitted; a rejection here means
		// the track ended before playback started, which stop() will clean up.
	});

	const grab = (options: { force: boolean }): CapturedFrame | null => {
		if (stopped || !context) return null;
		const width = video.videoWidth;
		const height = video.videoHeight;
		if (width === 0 || height === 0) return null;

		const size = computeCaptureSize(width, height, config.maxEdge);
		canvas.width = size.width;
		canvas.height = size.height;
		context.drawImage(video, 0, 0, size.width, size.height);

		const histogram = lumaHistogram(context.getImageData(0, 0, size.width, size.height).data);
		if (!options.force) {
			const skip = shouldSkipFrame({
				documentHidden: typeof document !== "undefined" && document.hidden,
				previousHistogram,
				nextHistogram: histogram,
				similarityThreshold: config.similarityThreshold,
			});
			if (skip) return null;
		}
		previousHistogram = histogram;

		const dataUrl = canvas.toDataURL("image/jpeg", config.jpegQuality);
		frameCount += 1;
		return {
			data: dataUrl.slice(dataUrl.indexOf(",") + 1),
			dataUrl,
			mimeType: "image/jpeg",
			width: size.width,
			height: size.height,
			capturedAt: Date.now(),
		};
	};

	const emit = (frame: CapturedFrame | null) => {
		if (!frame) return;
		for (const listener of listeners) {
			try {
				listener(frame);
			} catch (error) {
				console.warn("[keating:video] frame listener failed", error);
			}
		}
	};

	timer = setInterval(() => {
		if (listeners.size === 0) return;
		emit(grab({ force: false }));
	}, config.intervalMs);

	const stop = () => {
		if (stopped) return;
		stopped = true;
		if (timer !== null) clearInterval(timer);
		timer = null;
		listeners.clear();
		stream.getTracks().forEach((track) => track.stop());
		video.srcObject = null;
		try {
			video.remove();
		} catch {}
	};

	// A screen share ends when the user clicks the browser's "stop sharing"
	// chrome, which surfaces only as a track ending.
	stream.getVideoTracks().forEach((track) => track.addEventListener("ended", stop, { once: true }));

	return {
		stream,
		source: config.source,
		get frameCount() {
			return frameCount;
		},
		onFrame(listener) {
			listeners.add(listener);
			return () => listeners.delete(listener);
		},
		async captureFrameNow() {
			const frame = grab({ force: true });
			emit(frame);
			return frame;
		},
		stop,
	};
}

/**
 * Microphone capture on the audio rendering thread.
 *
 * The deprecated ScriptProcessorNode runs its callback on the main thread, so
 * any React render or tool execution during a live session shows up as dropped
 * or glitched microphone audio. An AudioWorklet runs on the audio thread and is
 * unaffected by main-thread work.
 *
 * The worklet is shipped as a source string and loaded from a blob URL rather
 * than a separate bundled entry point — worklet modules cannot share the app's
 * module graph anyway, and this keeps it working under any bundler config.
 */

/** Frames per posted chunk. ~85ms at 16kHz: small enough to stay responsive. */
const CHUNK_FRAMES = 1365;

const WORKLET_SOURCE = `
class PcmCaptureProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    this.chunkFrames = (options && options.processorOptions && options.processorOptions.chunkFrames) || ${CHUNK_FRAMES};
    this.buffer = new Float32Array(this.chunkFrames);
    this.offset = 0;
  }

  process(inputs) {
    const channel = inputs[0] && inputs[0][0];
    // No input yet (or the track ended): keep the processor alive regardless.
    if (!channel) return true;

    for (let i = 0; i < channel.length; i += 1) {
      this.buffer[this.offset] = channel[i];
      this.offset += 1;
      if (this.offset === this.chunkFrames) {
        // Convert on the audio thread so the main thread only sees bytes.
        const pcm = new Int16Array(this.chunkFrames);
        for (let j = 0; j < this.chunkFrames; j += 1) {
          const sample = Math.max(-1, Math.min(1, this.buffer[j]));
          pcm[j] = sample < 0 ? sample * 0x8000 : sample * 0x7fff;
        }
        this.port.postMessage(pcm.buffer, [pcm.buffer]);
        this.offset = 0;
      }
    }
    return true;
  }
}

registerProcessor("keating-pcm-capture", PcmCaptureProcessor);
`;

export const PCM_CAPTURE_PROCESSOR = "keating-pcm-capture";

let moduleUrl: string | null = null;

function workletModuleUrl(): string {
	if (moduleUrl === null) {
		moduleUrl = URL.createObjectURL(new Blob([WORKLET_SOURCE], { type: "application/javascript" }));
	}
	return moduleUrl;
}

export interface PcmCaptureHandle {
	readonly context: AudioContext;
	readonly stream: MediaStream;
	stop(): void;
}

/** Base64-encode raw PCM bytes for transports that carry audio inside JSON. */
export function encodePcmChunk(buffer: ArrayBuffer): string {
	const bytes = new Uint8Array(buffer);
	let binary = "";
	// Chunked to avoid blowing the argument limit on long buffers.
	const stride = 0x8000;
	for (let i = 0; i < bytes.length; i += stride) {
		binary += String.fromCharCode(...bytes.subarray(i, i + stride));
	}
	return btoa(binary);
}

/**
 * Capture microphone audio as base64 PCM chunks at the requested sample rate.
 * Falls back to a ScriptProcessorNode where AudioWorklet is unavailable.
 */
export async function startPcmCapture(options: {
	sampleRate: number;
	onChunk: (base64: string) => void;
}): Promise<PcmCaptureHandle> {
	if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
		throw new Error("Microphone unavailable for live voice.");
	}
	const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
	const context = new AudioContext({ sampleRate: options.sampleRate });
	const source = context.createMediaStreamSource(stream);

	let disposed = false;
	let teardown = () => {};

	if (context.audioWorklet) {
		await context.audioWorklet.addModule(workletModuleUrl());
		const node = new AudioWorkletNode(context, PCM_CAPTURE_PROCESSOR, {
			numberOfInputs: 1,
			numberOfOutputs: 0,
			processorOptions: { chunkFrames: CHUNK_FRAMES },
		});
		node.port.onmessage = (event: MessageEvent<ArrayBuffer>) => {
			if (!disposed) options.onChunk(encodePcmChunk(event.data));
		};
		source.connect(node);
		teardown = () => {
			node.port.onmessage = null;
			try { node.disconnect(); } catch {}
		};
	} else {
		const processor = context.createScriptProcessor(4096, 1, 1);
		processor.onaudioprocess = (event) => {
			if (disposed) return;
			const input = event.inputBuffer.getChannelData(0);
			const pcm = new Int16Array(input.length);
			for (let i = 0; i < input.length; i += 1) {
				const sample = Math.max(-1, Math.min(1, input[i]));
				pcm[i] = sample < 0 ? sample * 0x8000 : sample * 0x7fff;
			}
			options.onChunk(encodePcmChunk(pcm.buffer));
		};
		source.connect(processor);
		// A ScriptProcessorNode only runs while connected to a destination; the
		// output buffer is left silent so the mic is not echoed back.
		processor.connect(context.destination);
		teardown = () => {
			processor.onaudioprocess = null;
			try { processor.disconnect(); } catch {}
		};
	}

	return {
		context,
		stream,
		stop() {
			if (disposed) return;
			disposed = true;
			teardown();
			try { source.disconnect(); } catch {}
			try { void context.close(); } catch {}
			stream.getTracks().forEach((track) => track.stop());
		},
	};
}

/**
 * Plumbing shared by every duplex speech provider.
 *
 * Keating drives providers at different capability tiers, but a live session
 * must look the same to the rest of the app regardless of which provider is
 * behind it — persistence, replay, and the /live surface all consume the
 * canonical event stream. Keeping the bridge and the tool-call lifecycle here
 * (rather than duplicated per provider) is what makes the tier-parity test
 * meaningful.
 */
import type { RealtimeTelemetry } from "../observability";
import {
	conversationEvent,
	type ConversationEvent,
	type JsonValue,
	type ProtocolError,
} from "../protocol";
import type { LiveSpeechToolCall } from "../speech";

export type LiveProviderId = "openai" | "google";

export function randomId(prefix: string): string {
	const id = typeof crypto !== "undefined" && typeof crypto.randomUUID === "function"
		? crypto.randomUUID()
		: `${Date.now()}-${Math.random().toString(36).slice(2)}`;
	return `${prefix}-${id}`;
}

export function jsonValue(value: unknown): JsonValue {
	if (value === undefined) return null;
	try {
		return JSON.parse(JSON.stringify(value)) as JsonValue;
	} catch {
		return String(value);
	}
}

export function jsonRecord(value: unknown): Record<string, JsonValue> {
	const converted = jsonValue(value);
	return converted && typeof converted === "object" && !Array.isArray(converted)
		? converted as Record<string, JsonValue>
		: {};
}

export function protocolError(error: unknown, code: string, provider: LiveProviderId): ProtocolError {
	return {
		code,
		message: error instanceof Error ? error.message : String(error),
		provider,
	};
}

export interface RealtimeCanonicalBridge {
	readonly sessionId: string;
	readonly runId: string;
	emit<T extends ConversationEvent["type"]>(
		type: T,
		payload: Extract<ConversationEvent, { type: T }>["payload"],
	): void;
}

export function createRealtimeCanonicalBridge(
	onEvent?: (event: ConversationEvent) => void,
	ids: { sessionId?: string; runId?: string } = {},
): RealtimeCanonicalBridge {
	const sessionId = ids.sessionId ?? randomId("voice-session");
	const runId = ids.runId ?? randomId("voice-run");
	let sequence = 0;
	return {
		sessionId,
		runId,
		emit(type, payload) {
			if (!onEvent) return;
			onEvent(conversationEvent(type, payload as never, {
				id: randomId("voice-event"),
				sequence: sequence++,
				timestamp: new Date().toISOString(),
				sessionId,
				runId,
			}));
		},
	};
}

export interface LiveToolCallOptions {
	call: LiveSpeechToolCall;
	provider: LiveProviderId;
	canonical: RealtimeCanonicalBridge;
	telemetry: RealtimeTelemetry;
	execute: (call: LiveSpeechToolCall) => Promise<unknown>;
	/** Send a successful result back over the provider's transport. */
	respond: (callId: string, output: unknown) => void;
	/**
	 * Send a failure back over the provider's transport. Providers differ in
	 * whether they have a dedicated error shape, so each supplies its own.
	 */
	respondError: (callId: string, message: string) => void;
}

/**
 * Run one tool call through the canonical lifecycle.
 *
 * The requested/started events are emitted before e…142 tokens truncated…emit("tool.started", { callId: call.callId });
	telemetry.emit("tool.started", { provider, toolName: call.name });
	const startedAt = telemetry.start();

	try {
		const output = await execute(call);
		canonical.emit("tool.completed", { callId: call.callId, result: jsonValue(output) });
		telemetry.emit(
			"tool.completed",
			{ provider, toolName: call.name, outcome: "success" },
			telemetry.durationSince(startedAt),
		);
		respond(call.callId, output);
	} catch (error) {
		canonical.emit("tool.failed", {
			callId: call.callId,
			error: protocolError(error, "tool_execution_failed", provider),
		});
		telemetry.emit(
			"tool.completed",
			{ provider, toolName: call.name, outcome: "failed" },
			telemetry.durationSince(startedAt),
		);
		respondError(call.callId, error instanceof Error ? error.message : String(error));
	}
}

/** Parse a provider's JSON-encoded tool arguments without throwing. */
export function parseToolArguments(raw: unknown): Record<string, unknown> {
	if (raw && typeof raw === "object" && !Array.isArray(raw)) return raw as Record<string, unknown>;
	if (typeof raw !== "string" || raw.length === 0) return {};
	try {
		const parsed = JSON.parse(raw);
		return parsed && typeof parsed === "object" && !Array.isArray(parsed)
			? parsed as Record<string, unknown>
			: {};
	} catch {
		return {};
	}
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Camera, MonitorUp, Power } from "lucide-react";

import { Nav } from "../components/Nav";
import { css, cx } from "../../styled-system/css";
import {
	getLiveSpeechBridge,
	getSpeechProvider,
	loadWebSpeechSettings,
	primeSpeechAudio,
	resolveSpeechRealtimeTier,
	speechErrorMessage,
	type LiveSpeechSession,
	type LiveSpeechState,
} from "../keating/speech";
import { startVideoCapture, type VideoCaptureHandle } from "../keating/video-capture";
import type { ConversationEvent } from "../keating/protocol";
import { getProviderApiKey } from "../lib/provider-models";

/**
 * The live session surface.
 *
 * Keating's mascot is a CRT monitor with a face, so a live A/V session gets
 * rendered as exactly that: the learner's camera feed becomes the phosphor
 * screen behind the bezel, and Keating's own face takes over whenever he has
 * nothing to look at. Status, tools, and transcript are all terminal readouts,
 * matching the boot sequence and the landing hero.
 */

const STATE_LABEL: Record<LiveSpeechState, string> = {
	connecting: "connecting",
	listening: "listening",
	speaking: "speaking",
	closed: "standby",
};

interface ToolEntry {
	callId: string;
	name: string;
	status: "running" | "completed" | "failed";
}

interface TranscriptEntry {
	role: "user" | "assistant";
	text: string;
}

/**
 * Dotted leader between a label and its status, as in the boot sequence.
 *
 * The dots are a border rather than repeated glyphs: a run of non-breaking
 * characters contributes its full width to max-content sizing and will drag the
 * whole grid column wider than its cell.
 */
function Leader({ label, value, tone }: { label: string; value: string; tone?: "ok" | "fail" | "pending" }) {
	return (
		<div className={css({ display: "flex", alignItems: "baseline", gap: "0.5rem", fontSize: "0.8125rem", minWidth: 0 })}>
			<span className={css({ minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" })}>
				{label}
			</span>
			<span
				aria-hidden="true"
				className={css({
					flex: "1 1 auto",
					minWidth: "0.75rem",
					alignSelf: "center",
					borderBottom: "1px dotted currentColor",
					opacity: 0.35,
				})}
			/>
			<span
				className={css({
					whiteSpace: "nowrap",
					flexShrink: 0,
					color: tone === "fail"
						? "var(--red)"
						: tone === "pending"
							? "var(--amber)"
							: "var(--phosphor)",
				})}
			>
				{value}
			</span>
		</div>
	);
}

export function Live() {
	const settings = useMemo(() => loadWebSpeechSettings(), []);
	const tier = useMemo(() => resolveSpeechRealtimeTier(settings), [settings]);

	const [state, setState] = useState<LiveSpeechState>("closed");
	const [active, setActive] = useState(false);
	const [error, setError] = useState<string | null>(null);
	const [transcript, setTranscript] = useState<TranscriptEntry[]>([]);
	const [tools, setTools] = useState<ToolEntry[]>([]);
	const [framesSent, setFramesSent] = useState(0);
	const [firstAudioMs, setFirstAudioMs] = useState<number | null>(null);
	const [videoLive, setVideoLive] = useState(false);

	const sessionRef = useRef<LiveSpeechSession | null>(null);
	const videoRef = useRef<VideoCaptureHandle | null>(null);
	const abortRef = useRef<AbortController | null>(null);
	const previewRef = useRef<HTMLVideoElement | null>(null);
	const transcriptRef = useRef<HTMLDivElement | null>(null);
	const startedAtRef = useRef<number>(0);

	const appendTranscript = useCallback((role: "user" | "assistant", text: string) => {
		if (!text) return;
		setTranscript((prev) => {
			const last = prev[prev.length - 1];
			// Deltas from the same speaker coalesce; a change of speaker starts a
			// new line.
			if (last && last.role === role) {
				return [...prev.slice(0, -1), { role, text: last.text + text }];
			}
			return [...prev, { role, text }];
		});
	}, []);

	// Keep the newest line in view without yanking the page around.
	useEffect(() => {
		const node = transcriptRef.current;
		if (node) node.scrollTop = node.scrollHeight;
	}, [transcript]);

	const stop = useCallback(() => {
		abortRef.current?.abort();
		abortRef.current = null;
		void sessionRef.current?.stop().catch(() => {});
		sessionRef.current = null;
		videoRef.current?.stop();
		videoRef.current = null;
		if (previewRef.current) previewRef.current.srcObject = null;
		setVideoLive(false);
		setActive(false);
		setState("closed");
	}, []);

	// A live session holds the microphone, the camera, and a paid socket; it
	// must not survive the user navigating away.
	useEffect(() => stop, [stop]);

	const onConversationEvent = useCallback((event: ConversationEvent) => {
		switch (event.type) {
			case "tool.requested":
				setTools((prev) => [
					...prev,
					{ callId: event.payload.callId, name: event.payload.name, status: "running" },
				]);
				break;
			case "tool.completed":
			case "tool.failed":
				setTools((prev) => prev.map((entry) =>
					entry.callId === event.payload.callId
						? { ...entry, status: event.type === "tool.completed" ? "completed" : "failed" }
						: entry));
				break;
			default:
				break;
		}
	}, []);

	const start = useCallback(async () => {
		setError(null);
		setTranscript([]);
		setTools([]);
		setFramesSent(0);
		setFirstAudioMs(null);
		setState("connecting");
		setActive(true);
		startedAtRef.current = Date.now();

		const abort = new AbortController();
		abortRef.current = abort;

		try {
			// Browsers only unlock audio playback inside a user gesture, and this
			// runs from the power button's handler.
			await primeSpeechAudio();

			const provider = await getSpeechProvider(settings.providerId);
			if (!provider?.startLiveSession) {
				throw new Error("This speech provider cannot hold a live session. Pick OpenAI Realtime or Gemini Live in Settings → Speech.");
			}

			let video: VideoCaptureHandle | null = null;
			if (settings.videoEnabled && tier.video) {
				try {
					video = await startVideoCapture({
						source: settings.videoSource,
						intervalMs: settings.frameIntervalMs,
					});
					videoRef.current = video;
					if (previewRef.current) {
						previewRef.current.srcObject = video.stream;
						void previewRef.current.play().catch(() => {});
					}
					video.onFrame(() => setFramesSent((count) => count + 1));
					setVideoLive(true);
				} catch (err) {
					// Vision is optional; a declined camera prompt must not cost the
					// learner their voice session.
					console.warn("[keating:live] video capture unavailable", err);
					setError(speechErrorMessage(err, "Camera or screen capture was unavailable. Continuing with audio only."));
				}
			}

			const bridge = getLiveSpeechBridge();
			const session = await provider.startLiveSession({
				settings,
				getApiKey: getProviderApiKey,
				signal: abort.signal,
				instructions: bridge?.instructions,
				history: bridge?.history,
				tools: bridge?.tools,
				video,
				onToolCall: bridge ? (call) => bridge.execute(call, abort.signal) : undefined,
				onConversationEvent,
				onState: (next) => {
					setState(next);
					if (next === "speaking") {
						setFirstAudioMs((current) => current ?? Date.now() - startedAtRef.current);
					}
				},
				onUserTranscript: (text) => appendTranscript("user", text),
				onAssistantTranscript: (text) => appendTranscript("assistant", text),
				onError: (err) => setError(err.message),
			});
			sessionRef.current = session;
		} catch (err) {
			setError(speechErrorMessage(err, "The live session could not be started."));
			stop();
		}
	}, [appendTranscript, onConversationEvent, settings, stop, tier.video]);

	const speaking = state === "speaking";

	return (
		<div className={cx("retro-layout", "retro-page")}>
			<Nav />
			<main className={css({ maxWidth: "68rem", marginInline: "auto", padding: "1.5rem", display: "grid", gap: "1.5rem" })}>
				<header className={css({ display: "grid", gap: "0.5rem" })}>
					<div className={cx("prompt", css({ fontSize: "0.8125rem", opacity: 0.75 }))}>
						keating --live --tier={tier.tier}
					</div>
					<h1 className={css({ fontFamily: "var(--mono-display)", fontSize: "1.75rem", fontWeight: 700, lineHeight: 1.2 })}>
						{tier.label}
					</h1>
					{tier.capReason && (
						<p className={css({ fontSize: "0.875rem", opacity: 0.75, maxWidth: "48rem" })}>
							{tier.capReason}
						</p>
					)}
				</header>

				{error && (
					<div
						role="alert"
						className={css({
							border: "1px solid var(--red)",
							borderRadius: "0.375rem",
							padding: "0.75rem 1rem",
							fontSize: "0.875rem",
							color: "var(--red)",
							background: "color-mix(in srgb, var(--red) 8%, transparent)",
						})}
					>
						{error}
					</div>
				)}

				<div className={css({ display: "grid", gap: "1.5rem", gridTemplateColumns: "minmax(0, 1fr)", lg: { gridTemplateColumns: "minmax(0, 1.15fr) minmax(0, 1fr)" } })}>
					{/* The viewport — Keating's CRT face, showing whatever he can see. */}
					{/* minmax(0, 1fr) so a wide child can never stretch the column. */}
					<section className={css({ display: "grid", gridTemplateColumns: "minmax(0, 1fr)", gap: "1rem", alignContent: "start", minWidth: 0 })}>
						<div
							className={cx(
								"crt",
								"terminal-glow",
								css({
									position: "relative",
									overflow: "hidden",
									aspectRatio: "4 / 3",
									// Never let the viewport eat a whole phone screen.
									maxHeight: "min(56dvh, 30rem)",
									minWidth: 0,
									borderRadius: "0.75rem",
									border: "3px solid var(--terminal-edge)",
									background: "var(--terminal)",
									// Column flow: content region above, status row below, so
									// nothing can overlap at any viewport size.
									display: "flex",
									flexDirection: "column",
									transitionProperty: "box-shadow, border-color",
									transitionDuration: "300ms",
								}),
								// The bezel brightens while Keating is talking, so the
								// speaking state is legible from across a room.
								speaking ? css({ borderColor: "var(--phosphor)" }) : "",
							)}
						>
						{/* Content region: the feed, or Keating's own face when blind. */}
							<div className={css({ position: "relative", flex: 1, minHeight: 0, display: "grid", placeItems: "center", overflow: "hidden" })}>
								<video
									ref={previewRef}
									muted
									playsInline
									className={css({
										position: "absolute",
										inset: 0,
										width: "100%",
										height: "100%",
										objectFit: "cover",
										// Tint the feed toward phosphor so it reads as part of
										// the monitor rather than a webcam pasted on top.
										filter: "saturate(0.75) contrast(1.05)",
										display: videoLive ? "block" : "none",
									})}
								/>

								{!videoLive && (
									<div className={css({ display: "grid", gap: "0.5rem", justifyItems: "center", padding: "0.75rem", textAlign: "center" })}>
										<img
											src="/brand/mascot-head.png"
											alt=""
											className={cx(
												css({ width: "4rem", md: { width: "5.5rem" }, height: "auto", imageRendering: "pixelated" }),
												speaking ? css({ animation: "pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite" }) : "",
											)}
										/>
										<p className={cx("font-terminal", css({ color: "var(--phosphor-dim)", fontSize: "0.9375rem", letterSpacing: "0.04em" }))}>
											{tier.video ? "NO VIDEO INPUT" : "THIS MODEL HAS NO VISION"}
										</p>
										{tier.video && (
											// Supplementary guidance; the phone viewport is too
											// short to carry it alongside the mascot.
											<p className={css({ display: "none", md: { display: "block" }, color: "var(--phosphor-dim)", fontSize: "0.75rem", opacity: 0.7, maxWidth: "16rem" })}>
												Enable the camera in Settings → Speech.
											</p>
										)}
									</div>
								)}
							</div>

						{/* Status bar, in flow along the bottom edge of the bezel. */}
							<div
								className={cx(
									"font-terminal",
									css({
										flexShrink: 0,
										display: "flex",
										alignItems: "center",
										justifyContent: "space-between",
										gap: "0.5rem",
										paddingInline: "0.75rem",
										paddingBlock: "0.375rem",
										borderTop: "1px solid color-mix(in srgb, var(--phosphor) 18%, transparent)",
										background: "color-mix(in srgb, var(--terminal) 88%, black)",
										fontSize: "0.875rem",
										letterSpacing: "0.06em",
									}),
								)}
							>
								<span
									className={cx(
										active && state !== "closed" ? "cursor-blink" : "",
										css({
											color: speaking ? "var(--phosphor)" : "var(--phosphor-dim)",
											textShadow: speaking ? "0 0 8px color-mix(in srgb, var(--phosphor) 60%, transparent)" : "none",
											whiteSpace: "nowrap",
											overflow: "hidden",
											textOverflow: "ellipsis",
										}),
									)}
								>
									{`> ${STATE_LABEL[state]}`}
								</span>

								{videoLive && (
									<span
										className={css({
											display: "inline-flex",
											alignItems: "center",
											gap: "0.375rem",
											flexShrink: 0,
											color: "var(--phosphor)",
										})}
									>
										{settings.videoSource === "screen" ? <MonitorUp size={12} /> : <Camera size={12} />}
										{settings.videoSource === "screen" ? "SCREEN" : "CAM"}
										{tier.videoRoute === "sampled" ? " · SAMPLED" : " · LIVE"}
									</span>
								)}
							</div>
						</div>

						<button
							type="button"
							onClick={active ? stop : () => void start()}
							className={cx(
								"font-terminal",
								css({
									display: "inline-flex",
									alignItems: "center",
									justifyContent: "center",
									gap: "0.5rem",
									width: "100%",
									minHeight: "3rem",
									borderRadius: "0.375rem",
									border: "2px solid",
									fontSize: "1.25rem",
									letterSpacing: "0.08em",
									cursor: "pointer",
									transitionProperty: "background-color, color, border-color, box-shadow, transform",
									transitionDuration: "150ms",
									_active: { transform: "translate(1px, 1px)" },
								}),
								active
									? css({
										borderColor: "var(--red)",
										color: "var(--red)",
										background: "color-mix(in srgb, var(--red) 10%, transparent)",
										boxShadow: "2px 2px 0 color-mix(in srgb, var(--red) 45%, transparent)",
									})
									: css({
										borderColor: "var(--accent-green)",
										color: "var(--accent-green)",
										background: "color-mix(in srgb, var(--accent-green) 10%, transparent)",
										boxShadow: "2px 2px 0 color-mix(in srgb, var(--accent-green) 45%, transparent)",
										_hover: { background: "color-mix(in srgb, var(--accent-green) 18%, transparent)" },
									}),
							)}
						>
							<Power size={18} />
							{active ? "END SESSION" : "START SESSION"}
						</button>

						{/* Boot-style capability readout. */}
						<div className={cx("font-terminal", css({ display: "grid", gap: "0.25rem", padding: "0.875rem 1rem", border: "1px solid var(--line)", borderRadius: "0.375rem" }))}>
							<Leader label="audio duplex" value="[OK]" />
							<Leader
								label="vision"
								value={tier.videoRoute === "native" ? "[LIVE LANE]" : tier.videoRoute === "sampled" ? "[SAMPLED]" : "[NONE]"}
								tone={tier.videoRoute === "none" ? "fail" : "ok"}
							/>
							<Leader label="tool calls" value={tier.tier > 0 ? "[OK]" : "[NONE]"} tone={tier.tier > 0 ? "ok" : "fail"} />
							<Leader label="frames sent" value={String(framesSent)} tone="pending" />
							<Leader
								label="first audio"
								value={firstAudioMs === null ? "--" : `${(firstAudioMs / 1000).toFixed(1)}s`}
								tone="pending"
							/>
						</div>
					</section>

					{/* Transcript and tool feed, as terminal output. */}
					{/* Flex column so the transcript reliably absorbs the leftover
					    height and the tool feed stays pinned below it. */}
					<section className={css({ display: "flex", flexDirection: "column", gap: "1rem", minWidth: 0 })}>
						<div
							ref={transcriptRef}
							// `terminal-window` carries its own scanline ::before; adding
							// `crt` here would collide on the same pseudo-element.
							className={cx(
								"terminal-window",
								css({
									position: "relative",
									borderRadius: "0.5rem",
									border: "1px solid var(--terminal-edge)",
									padding: "1rem",
									// Fixed on phones so the transcript and the viewport both
									// stay reachable; on wide screens it fills the column.
									height: "14rem",
									md: { height: "18rem" },
									lg: { height: "auto", flex: 1, minHeight: "18rem" },
									overflowY: "auto",
									overflowWrap: "anywhere",
									fontSize: "0.9375rem",
									lineHeight: 1.55,
								}),
							)}
						>
							{transcript.length === 0 ? (
								<p className={css({ color: "var(--phosphor-dim)" })}>
									{active ? "> awaiting speech_" : "> press start to begin_"}
								</p>
							) : (
								transcript.map((entry, index) => (
									<p key={index} className={css({ marginBottom: "0.5rem" })}>
										<span className={css({ color: entry.role === "user" ? "var(--amber)" : "var(--phosphor)", opacity: 0.9 })}>
											{entry.role === "user" ? "YOU> " : "KEATING> "}
										</span>
										<span className={css({ color: entry.role === "user" ? "var(--phosphor-dim)" : "var(--phosphor)" })}>
											{entry.text}
										</span>
									</p>
								))
							)}
						</div>

						<div className={cx("font-terminal", css({ display: "grid", gap: "0.25rem", padding: "0.875rem 1rem", border: "1px solid var(--line)", borderRadius: "0.375rem", minHeight: "6rem", alignContent: "start" }))}>
							<div className={css({ fontSize: "0.9375rem", opacity: 0.6, letterSpacing: "0.06em", marginBottom: "0.25rem" })}>
								TOOL CALLS
							</div>
							{tools.length === 0 ? (
								<p className={css({ fontSize: "0.9375rem", opacity: 0.55 })}>none yet</p>
							) : (
								tools.map((tool) => (
									<Leader
										key={`${tool.callId}-${tool.name}`}
										label={tool.name}
										value={tool.status === "running" ? "[····]" : tool.status === "completed" ? "[OK]" : "[FAIL]"}
										tone={tool.status === "running" ? "pending" : tool.status === "completed" ? "ok" : "fail"}
									/>
								))
							)}
						</div>
					</section>
				</div>
			</main>
		</div>
	);
}

