   247	function decodeBase64Pcm(base64: string): Int16Array {
   248		const binary = window.atob(base64);
   249		const bytes = new Uint8Array(binary.length);
   250		for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
   251		return new Int16Array(bytes.buffer);
   252	}
