   254	export function schedulePcmAudio(base64: string, sampleRate = RECEIVE_SAMPLE_RATE): boolean {
   255		const context = getAudioContext();
   256		if (!context) return false;
   257	
   258		const pcm = decodeBase64Pcm(base64);
   259		if (pcm.length === 0) return false;
   260	
   261		const buffer = context.createBuffer(1, pcm.length, sampleRate);
   262		const channel = buffer.getChannelData(0);
   263		for (let i = 0; i < pcm.length; i += 1) channel[i] = pcm[i] / 32768;
   264	
   265		const source = context.createBufferSource();
   266		source.buffer = buffer;
   267		source.connect(context.destination);
   268		const startAt = Math.max(context.currentTime + 0.03, scheduledUntil);
   269		source.start(startAt);
   270		scheduledUntil = startAt + buffer.duration;
   271		trackScheduledSource(source);
   272		return true;
   273	}
   274	
   275	function trackScheduledSource(source: AudioBufferSourceNode): void {
   276		scheduledSources.add(source);
   277		source.addEventListener("ended", () => scheduledSources.delete(source), { once: true });
   278	}
