   280	/**
   281	 * Cut off audio that has been queued but not yet played.
   282	 *
   283	 * Providers that stream PCM (rather than delivering a WebRTC track) can have
   284	 * seconds of assistant speech buffered ahead of the speaker. Without this, a
   285	 * learner interrupting would keep hearing the sentence they just cut off.
   286	 */
   287	export function stopScheduledAudio(): void {
   288		for (const source of scheduledSources) {
   289			try {
   290				source.stop();
   291			} catch {
   292				// Already stopped or never started; either way it is not audible.
   293			}
   294		}
   295		scheduledSources.clear();
   296		const context = getAudioContext();
   297		scheduledUntil = context ? context.currentTime : 0;
   298	}
