 40			const session = buildRealtimeSessionConfig(
 41				{ ...DEFAULT_WEB_SPEECH_SETTINGS, model: "gpt-realtime-2.1", voiceName: "cedar" },
 42			) as any;
 43	
 44			expect(session.turn_detection).toBeUndefined();
 45			expect(session.input_audio_transcription).toBeUndefined();
 46			expect(session.modalities).toBeUndefined();
 47	
 48			expect(session.output_modalities).toEqual(["audio"]);
 49			expect(session.audio.input.format).toEqual({ type: "audio/pcm", rate: 24000 });
 50			expect(session.audio.input.transcription).toEqual({ model: "gpt-4o-transcribe" });
 51			expect(session.audio.output.voice).toBe("cedar");
 52		});
 53	
 54		it("falls back to a supported voice rather than sending an unknown one", () => {
 55			const session = buildRealtimeSessionConfig(
 56				{ ...DEFAULT_WEB_SPEECH_SETTINGS, model: "gpt-realtime-2.1", voiceName: "Kore" },
 57			) as any;
 58			// "Kore" is a Gemini voice; switching providers must not break the session.
 59			expect(session.audio.output.voice).toBe("marin");
 60		});
 61	
 62		it("only sends a reasoning budget to models that accept one", () => {
 63			const reasoning = buildRealtimeSessionConfig(
 64				{ ...DEFAULT_WEB_SPEECH_SETTINGS, model: "gpt-realtime-2", reasoningEffort: "low" },
 65			) as any;
 66			expect(reasoning.reasoning).toEqual({ effort: "low" });
 67	
 68			for (const model of ["gpt-realtime", "gpt-4o-realtime-preview-2024-12-17"]) {
 69				const session = buildRealtimeSessionConfig({ ...DEFAULT_WEB_SPEECH_SETTINGS, model }) as any;
 70				expect(session.reasoning).toBeUndefined();
 71			}
 72		});
 73	
 74		it("omits tools entirely when there are none, rather than sending an empty list", () => {
 75			const session = buildRealtimeSessionConfig({ ...DEFAULT_WEB_SPEECH_SETTINGS, model: "gpt-realtime-2.1" }) as any;
 76			expect(session.tools).toBeUndefined();
 77			expect(session.tool_choice).toBeUndefined();
 78		});
