 80		it("sends a sampled frame as context, never as a turn", () => {
 81			// Realtime has no video lane, so vision arrives as a still image on the
 82			// conversation. Following it with response.create would make the model
 83			// narrate the camera feed instead of waiting for the learner.
 84			const item = realtimeImageItem("data:image/jpeg;base64,AAAA") as any;
