 93			expect(realtimeHistoryItem({ role: "user", text: "why does this compile?" }) as any).toEqual({
 94				type: "conversation.item.create",
 95				item: {
 96					type: "message",
 97					role: "user",
 98					content: [{ type: "input_text", text: "why does this compile?" }],
 99				},
100			});
101			expect((realtimeHistoryItem({ role: "assistant", text: "look at the lifetime" }) as any).item.content[0].type)
102				.toBe("output_text");
103		});
104	
105		it("encodes function outputs for the model to continue speaking", () => {
106			expect(realtimeFunctionOutput("call-1", { ok: true })).toEqual({
107				type: "conversation.item.create",
108				item: { type: "function_call_output", call_id: "call-1", output: '{"ok":true}' },
109			});
110		});
