114			expect(negotiated.ruleId).toBe("openai-realtime-vision");
115			expect(negotiated.realtimeAudio).toBe("native");
116			expect(negotiated.transport).toBe("webrtc");
117			expect(negotiated.toolCalls).toBe("native");
118			expect(negotiated.missing).toEqual([]);
119		});
