 22	async function synthesize(request: SpeechSynthesisRequest): Promise<SpeechSynthesisResult> {
 23		const { utterance, settings, getApiKey, signal } = request;
 24		const apiKey = await getApiKey("google");
 25		if (!apiKey) {
 26			throw new Error("No Google API key configured. Sign in to Google in Settings → Providers & Models.");
 27		}
