137	function encodePcmBase64(input: Float32Array): string {
138		const pcm = new Int16Array(input.length);
139		for (let i = 0; i < input.length; i += 1) {
140			const sample = Math.max(-1, Math.min(1, input[i]));
141			pcm[i] = sample < 0 ? sample * 0x8000 : sample * 0x7fff;
142		}
143		const bytes = new Uint8Array(pcm.buffer);
144		let binary = "";
145		for (let i = 0; i < bytes.length; i += 1) binary += String.fromCharCode(bytes[i]);
146		return window.btoa(binary);
147	}
