149	async function startLiveSession(request: LiveSpeechRequest): Promise<LiveSpeechSession> {
150		const { settings, getApiKey, signal, instructions, onState, onUserTranscript, onAssistantTranscript, onError } = request;
151		const apiKey = await getApiKey("google");
152		if (!apiKey) {
153			throw new Error("No Google API key configured. Sign in to Google in Settings → Providers & Models.");
154		}
155		if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) {
156			throw new Error("Microphone unavailable for live voice.");
157		}
158	
159		const { GoogleGenAI, Modality } = await import("@google/genai");
160		const ai = new GoogleGenAI({ apiKey });
161	
162		let state: LiveSpeechState = "connecting";
163		const setState = (next: LiveSpeechState) => {
164			if (state === "closed") return;
165			state = next;
166			onState?.(next);
167		};
168		setState("connecting");
169	
170		const micStream = await navigator.mediaDevices.getUserMedia({ audio: true });
171		// 16 kHz mono PCM is what Gemini Live expects on the input stream.
172		const captureContext = new AudioContext({ sampleRate: 16_000 });
173		const sourceNode = captureContext.createMediaStreamSource(micStream);
174		const processor = captureContext.createScriptProcessor(4096, 1, 1);
175	
176		let session: { sendRealtimeInput: (params: any) => void; close: () => void } | null = null;
177		let cleanedUp = false;
178		const cleanup = () => {
179			if (cleanedUp) return;
180			cleanedUp = true;
181			try { processor.disconnect(); } catch {}
182			try { sourceNode.disconnect(); } catch {}
183			try { captureContext.close(); } catch {}
184			micStream.getTracks().forEach((track) => track.stop());
185			try { session?.close(); } catch {}
186			setState("closed");
187		};
188	
189		if (signal?.aborted) {
190			cleanup();
191			throw new Error("Gemini Live aborted before start.");
192		}
193		signal?.addEventListener("abort", cleanup, { once: true });
194	
195		processor.onaudioprocess = (event) => {
196			if (!session || state === "closed") return;
197			const base64 = encodePcmBase64(event.inputBuffer.getChannelData(0));
198			try {
199				session.sendRealtimeInput({ audio: { data: base64, mimeType: "audio/pcm;rate=16000" } });
200			} catch {}
201		};
202	
203		try {
204			session = await withApiRetry(() => ai.live.connect({
205				model: settings.model || GEMINI_LIVE_SPEECH_MODEL,
206				callbacks: {
207					onmessage: (message: any) => {
208						for (const part of contentParts(message)) {
209							const data = part.inlineData?.data;
210							if (typeof data === "string" && data.length > 0) {
211								setState("speaking");
212								schedulePcmAudio(data);
213							}
214							if (typeof part.text === "string") onAssistantTranscript?.(part.text, false);
215						}
216						const outputText = message?.serverContent?.outputTranscription?.text;
217						if (typeof outputText === "string") onAssistantTranscript?.(outputText, false);
218						const inputText = message?.serverContent?.inputTranscription?.text;
219						if (typeof inputText === "string") onUserTranscript?.(inputText, false);
220						if (message?.serverContent?.turnComplete) setState("listening");
221					},
222					onerror: (event: ErrorEvent) => onError?.(new Error(event.message || "Gemini Live failed.")),
223					onclose: () => cleanup(),
224				},
225				config: {
226					responseModalities: [Modality.AUDIO],
227					outputAudioTranscription: {},
228					inputAudioTranscription: {},
229					systemInstruction:
230						instructions ||
231						"You are Keating, a warm Socratic tutor on a live voice call with a learner. Keep replies natural, concise, and conversational.",
232				},
233			}), { signal });
234		} catch (error) {
235			cleanup();
236			throw error;
237		}
238	
239		// Connecting the processor to the destination pumps onaudioprocess; the
240		// output buffer is left silent so the mic is not echoed back.
241		sourceNode.connect(processor);
242		processor.connect(captureContext.destination);
243		setState("listening");
244	
245		return {
246			get state() {
247				return state;
248			},
249			async stop() {
250				cleanup();
251			},
252		};
253	}
